// Claude's review tests for A33 (change a real response) in the page and the panel. agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

const patchMock = (extra: Partial<Mock> = {}): Mock => ({
  id: 'p', name: 'Beta off', enabled: true, method: 'POST', urlPattern: '/api/echo', source: 'manual', createdAt: 0,
  response: { status: 200, headers: {}, body: '', bodyEncoding: 'text', delayMs: 0 },
  reply: 'patch',
  patch: { status: 207, headers: { 'x-patched': '1' }, set: [{ path: 'user.flags.beta', value: 'false' }, { path: 'items.*.price', value: '0' }], remove: ['user.name'] },
  ...extra,
});

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(mocks: Mock[]): Promise<{ page: Page; panel: Page }> {
  const p: Project = { id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default', scenarios: [{ id: 'default', name: 'Default', mocks }] };
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

const BODY = JSON.stringify({ user: { name: 'Anna', flags: { beta: true } }, items: [{ price: 5 }, { price: 7 }] });
const CHANGED = { user: { flags: { beta: false } }, items: [{ price: 0 }, { price: 0 }] };

test('fetch and XHR get the real response, changed', async () => {
  const { page, panel } = await open([patchMock()]);
  try {
    const got = await page.evaluate(async (body) => {
      const f = await fetch('/api/echo', { method: 'POST', headers: { 'content-type': 'application/json' }, body });
      const fetchOut = { status: f.status, header: f.headers.get('x-patched'), body: await f.json() };
      const xhrOut = await new Promise<{ status: number; header: string | null; body: unknown }>((resolve) => {
        const x = new XMLHttpRequest();
        x.open('POST', '/api/echo');
        x.setRequestHeader('content-type', 'application/json');
        x.onload = () => resolve({ status: x.status, header: x.getResponseHeader('x-patched'), body: JSON.parse(x.responseText) });
        x.send(body);
      });
      return { fetchOut, xhrOut };
    }, BODY);
    expect(got.fetchOut).toEqual({ status: 207, header: '1', body: CHANGED });
    expect(got.xhrOut).toEqual({ status: 207, header: '1', body: CHANGED });
    const rows = panel.getByTestId('log-row').filter({ hasText: '/api/echo' });
    await expect(rows).toHaveCount(2);
    await rows.first().click();
    await expect(panel.getByTestId('answered-by')).toContainText('Beta off');
    await expect(panel.getByTestId('response-body')).toContainText('"beta": false');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a body that is not JSON passes through; a failed real call fails as before', async () => {
  const { page, panel } = await open([
    patchMock({ id: 'txt', patch: { status: 201, set: [{ path: 'a', value: '1' }] } }),
    patchMock({ id: 'down', method: 'GET', urlPattern: 'http://127.0.0.1:9/nothing', patch: { status: 200 } }),
  ]);
  try {
    const got = await page.evaluate(async () => {
      const r = await fetch('/api/echo', { method: 'POST', headers: { 'content-type': 'text/plain' }, body: 'hello' });
      let failed = '';
      try {
        await fetch('http://127.0.0.1:9/nothing');
      } catch (e) {
        failed = (e as Error).name;
      }
      return { status: r.status, text: await r.text(), failed };
    });
    expect(got).toEqual({ status: 201, text: 'hello', failed: 'TypeError' });
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the editor sets up a Change real reply, and the Test bar describes it without calling', async () => {
  const plain: Mock = { ...patchMock(), id: 'plain', name: 'Plain', reply: undefined, patch: undefined, response: { status: 200, headers: {}, body: '{}', bodyEncoding: 'text', delayMs: 0 } };
  const { page, panel } = await open([plain]);
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'Plain' }).click();
    await panel.getByTestId('reply-patch').click();
    await expect(panel.getByTestId('patch-view')).toBeVisible();
    await panel.getByTestId('patch-status').fill('503');
    await panel.getByTestId('patch-set-add').click();
    await panel.getByTestId('patch-set-path').fill('user.beta');
    await panel.getByTestId('patch-set-value').fill('false');
    await panel.getByTestId('patch-remove-add').click();
    await panel.getByTestId('patch-remove-path').fill('token');
    await panel.getByTestId('mock-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[0]).toMatchObject({
      reply: 'patch', patch: { status: 503, set: [{ path: 'user.beta', value: 'false' }], remove: ['token'] },
    });

    await panel.getByTestId('test-method').selectOption('POST');
    await panel.getByTestId('test-url').fill('/api/echo');
    await panel.getByTestId('test-run').click();
    await expect(panel.getByTestId('test-patch-summary')).toContainText('Changes the real response');
    await expect(panel.getByTestId('test-patch-summary')).toContainText('Set user.beta = false');
    await expect(panel.getByTestId('test-patch-summary')).toContainText('Remove token');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a binary body keeps its bytes; only status and headers change', async () => {
  const { page, panel } = await open([patchMock({ id: 'png', method: 'GET', urlPattern: '/api/logo.png', patch: { status: 201, headers: { 'x-patched': 'png' }, set: [{ path: 'a', value: '1' }] } })]);
  try {
    const got = await page.evaluate(async () => {
      const r = await fetch('/api/logo.png');
      const bytes = new Uint8Array(await r.arrayBuffer());
      return { status: r.status, header: r.headers.get('x-patched'), type: r.headers.get('content-type'), length: bytes.length, head: Array.from(bytes.slice(0, 8)) };
    });
    expect(got).toEqual({ status: 201, header: 'png', type: 'image/png', length: 10240, head: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] });
  } finally {
    await panel.close();
    await page.close();
  }
});
